<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {getAdminApi,type Overview} from './api'
const data=ref<Overview>(),error=ref('')
onMounted(async()=>{try{data.value=await getAdminApi().get<Overview>('overview/')}catch(e){error.value=(e as Error).message}})
const total=computed(()=>data.value?.tasks.reduce((n,x)=>n+Number(x.participant_count||0),0)||0),submitted=computed(()=>data.value?.tasks.reduce((n,x)=>n+Number(x.submitted_count||0),0)||0)
const cards=[['courses','课程','/manage/courses/'],['classes','课程班级','/manage/courses/'],['students','学生账号','/manage/users/'],['experiments','实验','/manage/data/']]
</script>
<template><div class="eyebrow">ADMINISTRATION / OVERVIEW</div><header class="heading"><div><h1>管理概览</h1><p>查看全平台教学组织与任务进展，处理需要关注的管理事项。</p></div><a class="management-action-link" href="/manage/courses/">管理课程 →</a></header><p v-if="error" class="error-block" role="alert">{{ error }}</p><p v-if="!data&&!error" role="status">正在加载管理概览…</p><template v-if="data"><div class="stats"><a v-for="[key,label,url] in cards" :key="key" class="stat stat-link" :href="url"><div class="stat-top">{{ label }}</div><strong>{{ data.metrics[key!] ?? 0 }}</strong><small>全平台统计</small></a></div><div class="overview-grid"><section class="card"><div class="card-header"><div><h2>最近班级任务进展</h2><p>最近 4 条任务 · 完成数 / 发布参与人数</p></div><a class="management-text-link" href="/manage/data/">查看全部 →</a></div><div class="task-summary"><div><strong>{{ submitted }}<span> / {{ total }}</span></strong><small>所列任务已提交 / 发布参与人次</small></div><div class="task-summary-right"><b>{{ total?Math.round(submitted/total*100):0 }}%</b><span>所列任务提交比例</span></div></div><a v-for="task in data.tasks.slice(0,4)" :key="task.id" class="progress-row" :href="task.detail_url||'/manage/data/'"><div><strong>{{ task.experiment_name || task.name }}</strong><small>{{ task.course_name }} · {{ task.class_name }}</small></div><div class="progress-info"><span class="badge">{{ task.status_label||task.status }}</span><span>{{ task.submitted_count }} / {{ task.participant_count }}</span><div class="progress-track"><i :style="{width:`${Number(task.participant_count)?Number(task.submitted_count)/Number(task.participant_count)*100:0}%`}" /></div></div><span class="chevron">›</span></a><p v-if="!data.tasks.length" class="empty">暂无班级任务。</p></section><section class="card attention"><div class="card-header"><div><h2>平台管理</h2><p>账号、资源与数据的统一入口</p></div></div><a class="attention-item" href="/manage/users/"><span class="attention-icon">◎</span><div><strong>{{ data.metrics.users }} 个平台账号</strong><p>查看账号状态与课程关联</p></div><span>›</span></a><a class="attention-item" href="/manage/resources/"><span class="attention-icon">▤</span><div><strong>{{ data.metrics.banks }} 个题库</strong><p>维护教学资源与课程知识点</p></div><span>›</span></a><a class="attention-item" href="/manage/data/"><span class="attention-icon">↓</span><div><strong>{{ data.metrics.exports }} 个导出任务</strong><p>查看任务状态与下载记录</p></div><span>›</span></a><div class="quiet-note">这里呈现真实业务记录，不代表服务器运行监控。</div></section></div><section class="card recent-card"><div class="card-header"><div><h2>近期操作</h2><p>谁在什么对象上执行了哪些操作</p></div><a class="management-text-link" href="/manage/audit/">查看操作记录 →</a></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>对象</th></tr></thead><tbody><tr v-for="row in data.recent_audit.slice(0,4)" :key="row.id"><td class="muted">{{ row.created_at }}</td><td>{{ row.actor_name }}</td><td>{{ row.action }}</td><td>{{ row.target || `${row.object_type} #${row.object_id}` }}</td></tr><tr v-if="!data.recent_audit.length"><td colspan="4" class="empty">暂无操作记录。</td></tr></tbody></table></div></section></template></template>
